class Solution {
public:
    int tallestBillboard(vector<int>& rods) {
        unordered_map<int, int> dp;
        dp[0] = 0;
        for (int x : rods) {
            auto cur = dp;
            for (auto& [diff, y] : cur) {
                dp[diff + x] = max(dp[diff + x], y);
                int new_diff = abs(diff - x);
                int new_y = y + min(diff, x);
                dp[new_diff] = max(dp[new_diff], new_y);
            }
        }
        return dp[0];
    }
};

class Solution {
    public int tallestBillboard(int[] rods) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int x : rods) {
            Map<Integer, Integer> cur = new HashMap<>(dp);
            for (Map.Entry<Integer, Integer> entry : cur.entrySet()) {
                int diff = entry.getKey(), y = entry.getValue();
                dp.put(diff + x, Math.max(dp.getOrDefault(diff + x, 0), y));
                int newDiff = Math.abs(diff - x);
                int newY = y + Math.min(diff, x);
                dp.put(newDiff, Math.max(dp.getOrDefault(newDiff, 0), newY));
            }
        }
        return dp.getOrDefault(0, 0);
    }
}

var tallestBillboard = function(rods) {
    let dp = new Map([[0, 0]]);
    for (const x of rods) {
        const cur = new Map(dp);
        for (const [diff, y] of cur.entries()) {
            dp.set(diff + x, Math.max(dp.get(diff + x) || 0, y));
            const newDiff = Math.abs(diff - x);
            const newY = y + Math.min(diff, x);
            dp.set(newDiff, Math.max(dp.get(newDiff) || 0, newY));
        }
    }
    return dp.get(0) || 0;
};
